package contracts

import (
	"io"
	"slices"
)

const SecretsFormat = "asservat-secrets/v1"
const SecretsMaxBytes = 384 << 10

// SecretsPlan is the Helm-rendered input of the `secrets` hook Job. It names
// the Secrets the Job creates once (never rotates); values are generated by
// the Job, never by Helm. Overridden Secrets are omitted, except the IDs
// Secret, which every other generated Secret depends on.
type SecretsPlan struct {
	Format      string                 `json:"format"`
	Namespace   string                 `json:"namespace"`
	Name        string                 `json:"name"`
	Mode        string                 `json:"mode"`
	IDs         SecretsIDs             `json:"ids"`
	AuditMAC    string                 `json:"auditMAC,omitempty"`
	ArtifactKey string                 `json:"artifactKey,omitempty"`
	SQL         []SecretsSQL           `json:"sql"`
	Postgres    bool                   `json:"postgres"`
	Keycloak    *SmallKeycloakSettings `json:"keycloak,omitempty"`
	ObjectStore *SmallSeaweedPlan      `json:"objectStore,omitempty"`
	OpenBao     *SmallOpenBaoSelection `json:"openBao,omitempty"`
	// Its password and roots remain separate selected operator Secrets.
	KeycloakExternalDatabase bool `json:"keycloakExternalDatabase,omitempty"`
	// ServingTLS are the peer listener Secrets (kubernetes.io/tls with
	// ca.crt) created once when no existing Secret or issuer is selected.
	ServingTLS []SecretsServingTLS `json:"servingTLS,omitempty"`
	// DownloadStore copies the download-read store credential into the
	// download workers' namespace (Pods mount only their own namespace's
	// Secrets), immutable, created once.
	DownloadStore *SecretsCopy `json:"downloadStore,omitempty"`
	// RemoteClusters are the joined mode=cluster clusters (values
	// clusters): with the bundled object store each gets its own regional
	// capabilities, scoped to its cluster ID (RemoteObjectStoreSecret).
	RemoteClusters []SecretsRemoteCluster `json:"remoteClusters,omitempty"`
}

type SecretsRemoteCluster struct {
	Name      string `json:"name"`
	ClusterID string `json:"clusterID"`
}

// RemoteObjectStorePrincipals are a joined cluster's regional executor
// capabilities (ADR-331), each scoped to that cluster's ID.
func RemoteObjectStorePrincipals() []string { return []string{"regional-write", "regional-history"} }

// RemoteObjectStoreSecret is the Secret (key credentials.json) of one
// joined cluster's regional capability: `<name>-s3-<principal>-<cluster>`.
// The secrets hook generates it with the bundled object store; with an
// external store the operator creates it.
func RemoteObjectStoreSecret(release, principal, cluster string) string {
	return release + "-s3-" + principal + "-" + cluster
}

// SecretsCopy names a Secret in the release namespace and its copy.
type SecretsCopy struct {
	Source    string `json:"source"`
	Namespace string `json:"namespace"`
	Secret    string `json:"secret"`
}

// SecretsServingTLS is one `<name>-<component>-tls` Secret and the DNS names
// of its leaf certificate.
type SecretsServingTLS struct {
	Secret   string   `json:"secret"`
	DNSNames []string `json:"dnsNames"`
}

// SecretsIDs names the `<name>-ids` Secret; Generate is false for an
// existingSecret override, which must already hold every ID key.
type SecretsIDs struct {
	Secret   string `json:"secret"`
	Generate bool   `json:"generate"`
}

// SecretsSQL is one `<name>-sql-<component>` Secret.
type SecretsSQL struct {
	Component string `json:"component"`
	Secret    string `json:"secret"`
}

// The keys of the `<name>-ids` Secret, mounted at /run/asservat/ids/<key>.
func InstallationIDKeys() []string {
	return []string{"installationID", "clusterID", "issuerEpoch", "permissionRootID", "browserRootID", "sessionEpoch", "roleSetupID", "peerID"}
}

// The keys of the `<name>-audit-mac` Secret.
const (
	AuditMACInputVersion   = "inputVersion"
	AuditMACInputKey       = "inputKey"
	AuditMACAccountVersion = "accountVersion"
	AuditMACAccountKey     = "accountKey"
)

// ArtifactKeySecretKey is the `<name>-artifact-key` Secret key holding the local
// artifact root keyset (asservat-local-keys/v1).
const ArtifactKeySecretKey = "keys.json"

// ObjectStoreCredentialFile is the key of each `<name>-s3-<principal>` Secret
// (OwnerStorageCredential JSON).
const ObjectStoreCredentialFile = "credentials.json"

// SQLComponentPurposes are the runtime roles of one component's
// `<name>-sql-<component>` Secret; each is stored as sql-<purpose>.json.
// Together the components cover every public, configuration and owner role.
func SQLComponentPurposes(component string) ([]string, bool) {
	switch component {
	case "hub-api":
		return append(PublicRuntimeHubRolePurposes(), OwnerIdentityRolePurposes()...), true
	case "hub-worker":
		out := ConfigurationRuntimeRolePurposes()
		out = append(out, "browser-settings")
		out = append(out, PublicRuntimeCaptureCleanupPurposes()...)
		out = append(out, PublicRuntimeConnectorMaintenancePurposes()...)
		out = append(out, CapacityRuntimePurposes()...)
		out = append(out, PublicRuntimePermissionPurposes()...)
		out = append(out, PublicRuntimeRetentionPurposes()...)
		out = append(out, PublicRuntimeWorkerConfigurationPurposes()...)
		return append(out, PublicRuntimeContextDeletionPurposes()...), true
	case "federation":
		return PublicRuntimeFederationPurposes(), true
	case "publisher":
		return PublicRuntimePublisherPurposes(), true
	case "key-service":
		return PublicRuntimeKeyServicePurposes(), true
	}
	return nil, false
}

// ObjectStorePrincipals are the bundled SeaweedFS principals with a
// `<name>-s3-<principal>` Secret; combined mode adds the local region's.
func ObjectStorePrincipals(mode string) []string {
	out := []string{"configuration-audit", "owner-audit", "federation-audit", "publisher-audit", "publisher-read", "download-read", "evidence-delete", "operation-cleanup", "operation-verify"}
	if mode == "combined" {
		out = append(out, "regional-write", "regional-history")
	}
	return slices.Clone(out)
}

// SmallOpenBaoSelection selects the bundled OpenBao image.
type SmallOpenBaoSelection struct {
	Image string `json:"image"`
}

type SmallKeycloakDatabase struct {
	Host     string `json:"host"`
	Port     int    `json:"port"`
	Database string `json:"database"`
	Username string `json:"username"`
}

func DecodeSecretsPlan(r io.Reader) (SecretsPlan, error) {
	return decodeClosedRPC[SecretsPlan](r, SecretsMaxBytes)
}

func DecodeSmallKeycloakSettings(r io.Reader) (SmallKeycloakSettings, error) {
	return decodeClosedRPC[SmallKeycloakSettings](r, SecretsMaxBytes)
}

// SQLComponents are the hub components with their own SQL credential Secret.
func SQLComponents() []string {
	return []string{"hub-api", "hub-worker", "federation", "publisher", "key-service"}
}
